import qs from 'qs';

/**
 * Get a value from the query string by key
 *
 * @param {string} key - key to retrieve value for
 * @param {string} queryString - Query string to use
 *
 * @return {string} value - The value return at the given key
 */
export const getQueryStringValue = (
  key,
  queryString = window.location.search,
) => {
  const values = qs.parse(queryString, { ignoreQueryPrefix: true });

  return values[key];
};

/**
 * Generates a new query string by adding to or updating a value in
 * the current window's query string.
 *
 * @param {string} key - Key to set in the query string
 * @param {string} value - Value to set in the query string
 * @param {string} queryString - Query string to use
 *
 * @return {string} queryString - New query string
 */
export const updatedQueryString = (
  key,
  value,
  queryString = window.location.search,
) => {
  const values = qs.parse(queryString, { ignoreQueryPrefix: true });
  const newQueryStringValue = qs.stringify(
    {
      ...values,
      [key]: value,
    },
    {
      encode: false,
      skipNulls: true,
    },
  );

  if (newQueryStringValue) {
    return `?${newQueryStringValue}`;
  }

  return '';
};

/**
 * Set the URL in the user's window using the given query string
 *
 * @param {string} newQueryStringValue - Query string to use at the end of URL
 */
export const setUrl = (newQueryStringValue) => {
  const { protocol, host, pathname } = window.location;
  const newUrl = `${protocol}//${host}${pathname}${newQueryStringValue}`;

  window.history.replaceState(null, null, newUrl);
};

/**
 * Get the query string parsed as an object
 *
 * @param {string} queryString - Query string to use
 *
 * @returns {object} Object - object containing query string data
 */
export const getParsedQueryStringAsObject = (
  queryString = window.location.search,
) => qs.parse(queryString, { ignoreQueryPrefix: true });
